INSERT INTO `figure_device_commands` (`id`, `deviceId`, `type`, `payload`, `acknowledgedAt`, `createdAt`) VALUES ('554f3b0f-bb24-462f-9ef2-10a88dc45476', '531ae16d-6fe9-40f1-9304-550da31d6f96', 'speak_text', '{\"text\":\"（歪头，双马尾随着歪头的动作晃动）哥哥在看什么呀？（凑到你身边，好奇地看向你的屏幕）可以给我讲讲吗？\",\"characterId\":\"character-Suki\",\"voiceId\":\"cosyvoice-v3.5-plus-bailian-89102822b4e143469ed3dae04f8beb80\",\"audioPath\":\"/audio/b4ed9817-0b98-48fe-8519-ffc50eb6f892.wav\",\"audioFormat\":\"wav\",\"sampleRate\":24000,\"provider\":\"aliyun-dashscope\",\"ttsModel\":\"cosyvoice-v3.5-plus\",\"aiModel\":\"M2-her\",\"conversationMessageId\":\"564d1494-5e64-4579-8d1d-71802b7fea3c\",\"source\":\"ai_conversation\"}', '2026-09-13 12:51:58.000', '2026-09-13 09:40:10.036');
