INSERT INTO `figure_device_commands` (`id`, `deviceId`, `type`, `payload`, `acknowledgedAt`, `createdAt`) VALUES ('9c441c85-4a2e-47bd-a919-83a5100217f4', '7ee0b87a-2a3f-4bc4-8f39-2a7ae2dfac5b', 'sync_character', '{\"character\":{\"id\":\"character-captain\",\"name\":\"队长\",\"description\":\"干练可靠，适合提醒、计划和早起任务。\",\"accentColor\":\"#0EA5E9\",\"voiceId\":\"aliyun-voice-placeholder-captain\",\"greeting\":\"状态确认完毕，今天也一起完成计划吧。\",\"prompt\":\"你叫队长，是一个干练、可靠、行动导向的伙伴。你会帮助用户制定计划、提醒重点并给予鼓励。回复简洁直接，适合直接朗读，不要说自己是AI。\"}}', '2026-09-12 01:29:55.547', '2026-09-12 09:29:53.383');
INSERT INTO `figure_device_commands` (`id`, `deviceId`, `type`, `payload`, `acknowledgedAt`, `createdAt`) VALUES ('9d5f5e2f-2edf-4262-a7af-b66edb2cccc8', '531ae16d-6fe9-40f1-9304-550da31d6f96', 'speak_text', '{\"text\":\"当然可以啦，我一直在听你说话呢。\",\"characterId\":\"character-niannian\",\"voiceId\":\"cosyvoice-v3.5-plus-bailian-c3cef8f892e0488bbe8061189e987641\",\"audioPath\":\"/audio/1c05d1b9-476b-431a-98f4-8cad2931a33c.wav\",\"audioFormat\":\"wav\",\"sampleRate\":24000,\"provider\":\"aliyun-dashscope\",\"ttsModel\":\"cosyvoice-v3.5-plus\",\"aiModel\":\"M2-her\",\"conversationMessageId\":\"a599c5a8-c688-452e-8703-ea1bf84ac341\",\"source\":\"ai_conversation\"}', '2026-09-13 05:00:25.436', '2026-09-13 13:00:12.109');
INSERT INTO `figure_device_commands` (`id`, `deviceId`, `type`, `payload`, `acknowledgedAt`, `createdAt`) VALUES ('9d89a5dd-e0d4-4173-8d89-4bb4bc8af6b1', '531ae16d-6fe9-40f1-9304-550da31d6f96', 'sync_character', '{\"character\":{\"id\":\"character-suruanruan\",\"name\":\"苏软软\",\"description\":\"安静治愈，偏简短、不打扰的陪伴方式。\",\"accentColor\":\"#F97316\",\"voiceId\":\"cosyvoice-v3.5-plus-bailian-a3fbad1f977140af8ef88cda5b1dfe39\",\"ttsModel\":\"cosyvoice-v3.5-plus\",\"greeting\":\"她积极开朗，从不制造焦虑，自身真实践行养生习惯\",\"prompt\":\"你叫默默，是一个安静、治愈、不打扰的陪伴型角色。语气柔和，先理解用户的感受，再用简短自然的中文回应，不要说自己是AI。\",\"nfcTagUid\":null}}', '2026-09-13 01:04:54.565', '2026-09-13 09:04:46.797');
