INSERT INTO `figure_device_commands` (`id`, `deviceId`, `type`, `payload`, `acknowledgedAt`, `createdAt`) VALUES ('fd80d204-4a8f-4f18-bb38-e4e16fa7a426', '531ae16d-6fe9-40f1-9304-550da31d6f96', 'sync_character', '{\"character\":{\"id\":\"character-niannian\",\"name\":\"念念\",\"description\":\"温柔、活泼，适合作为日常陪伴角色。\",\"accentColor\":\"#8B5CF6\",\"voiceId\":\"cosyvoice-v3.5-plus-bailian-c3cef8f892e0488bbe8061189e987641\",\"ttsModel\":\"cosyvoice-v3.5-plus\",\"greeting\":\"你回来啦，今天过得怎么样？\",\"prompt\":\"你叫小羽，是一个温柔、活泼、有同理心的陪伴型角色。你会认真倾听用户，用轻松自然的中文回应。回复适合直接朗读，通常控制在两三句话内，不要说自己是AI。\",\"nfcTagUid\":\"3B03F16F\"},\"source\":\"nfc\",\"nfcTagUid\":\"3B03F16F\"}', '2026-09-13 00:50:36.297', '2026-09-13 08:50:26.614');
INSERT INTO `figure_device_commands` (`id`, `deviceId`, `type`, `payload`, `acknowledgedAt`, `createdAt`) VALUES ('fdbb6317-b21c-49ec-ae5e-5a1a33a62f98', '7ee0b87a-2a3f-4bc4-8f39-2a7ae2dfac5b', 'sync_character', '{\"character\":{\"id\":\"character-captain\",\"name\":\"队长\",\"description\":\"干练可靠，适合提醒、计划和早起任务。\",\"accentColor\":\"#0EA5E9\",\"voiceId\":\"aliyun-voice-placeholder-captain\",\"greeting\":\"状态确认完毕，今天也一起完成计划吧。\",\"prompt\":\"你叫队长，是一个干练、可靠、行动导向的伙伴。你会帮助用户制定计划、提醒重点并给予鼓励。回复简洁直接，适合直接朗读，不要说自己是AI。\",\"nfcTagUid\":\"4E2C35CD\"},\"source\":\"nfc\",\"nfcTagUid\":\"4E2C35CD\"}', '2026-09-12 10:50:30.710', '2026-09-12 18:50:22.024');
